import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class UserProfileServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(UserProfileServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String userId = request.getParameter("id");
        String fields = request.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            response.sendError(400, "Missing id parameter");
            return;
        }

        // Validate userId is numeric
        if (!userId.matches("^[0-9]+$")) {
            response.sendError(400, "Invalid id format");
            return;
        }

        // fields parameter allows selecting which columns to return
        // defaults to safe set if not specified
        String columnList = "username, email, created_at";
        if (fields != null && !fields.isEmpty()) {
            // Allow caller to specify columns for API flexibility
            columnList = fields;
        }

        String query = "SELECT " + columnList + " FROM user_profiles WHERE user_id = " + userId;
        logger.info("Executing profile query for user: " + userId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);
            response.setContentType("application/json");
            PrintWriter out = response.getWriter();

            out.print("{");
            if (rs.next()) {
                ResultSetMetaData meta = rs.getMetaData();
                int colCount = meta.getColumnCount();
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnName(i) + "\":");
                    String val = rs.getString(i);
                    if (val == null) {
                        out.print("null");
                    } else {
                        out.print("\"" + val.replace("\"", "\\\"") + "\"");
                    }
                }
            } else {
                response.setStatus(404);
                out.print("\"error\": \"User not found\"");
            }
            out.print("}");
            out.flush();

        } catch (SQLException e) {
            logger.warning("Database error: " + e.getMessage());
            response.sendError(500, "Internal server error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        // Update profile - uses PreparedStatement (safe)
        String userId = request.getParameter("id");
        String newEmail = request.getParameter("email");
        String newBio = request.getParameter("bio");

        if (userId == null || !userId.matches("^[0-9]+$")) {
            response.sendError(400, "Invalid id");
            return;
        }

        String updateSql = "UPDATE user_profiles SET email = ?, bio = ? WHERE user_id = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement pstmt = conn.prepareStatement(updateSql)) {
            pstmt.setString(1, newEmail);
            pstmt.setString(2, newBio);
            pstmt.setInt(3, Integer.parseInt(userId));
            int rows = pstmt.executeUpdate();

            response.setContentType("application/json");
            response.getWriter().print("{\"updated\": " + rows + "}");
        } catch (SQLException e) {
            logger.warning("Update error: " + e.getMessage());
            response.sendError(500, "Internal server error");
        }
    }
}
